sys_variable_value.value:
(function execute(inputs, outputs) {
var util = new VendorRiskUtils();

var result = util.calculateRiskScore(inputs.vendor_sys_id);

outputs.risk_score = result.score;
outputs.risk_level = result.level;
})(inputs, outputs);

